import React, { useEffect, createRef, useRef } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import Statistics from 'components/common/Analytics/Statistics'
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import ReactLoader from 'components/common/reactLoading';
import classNames from 'classnames'
import { fetchPlanHatApi } from 'redux/actions/common'
import OverviewBoxes from 'components/common/Analytics/OverviewBoxes'
import PendingLoaderInfo from 'components/common/PendingLoaderInfo'
import { useIsAppType } from 'hooks/useIsAppType';
import useSessionAnalyticsAPI from './hooks/useSessionAnalyticsAPI'

const chartRef = createRef()
const insideLoader = (
  <>
    <PendingLoaderInfo preText="Computing chart data" />
    <ReactLoader />
  </>
)
const defaultArgs = {
  grpList: [
    {
        "table": "session",
        "attribute": "session_period_day",
        "tooltip": "Day on which session was recorded.",
        "period": 86400,
        "display": "day",
        "time_zone_offset": -345
    }
],
}
const SessionStatistics = ({ isNewSession }) => {
  const {
    statsBoxes: statBoxesResponse,
    uniqueUserBox,
    aggregation_list: aggregationList,
    selectedBox,
    selectedTab,
    groupingOptions,
    graphData,
    group_list: groupList,
    series_plot_options: seriesPlotOptions,
    loader
  } = useSelector((state) => state.sessionStatisticsReducer);
  const isMounted = useRef(false);

  const { appId } = useSelector(state => state.urlReducer);
  const isWebApp = useIsAppType( 'web' );

  const dispatch = useDispatch()
  const { callAnalyticsApi } = useSessionAnalyticsAPI();

  useEffect(() => {
    dispatch(fetchPlanHatApi({ action: 'Entered session analytics' }))
  }, [])

  useEffect(() => {
    if (!isMounted.current) {
      callAnalyticsApi( undefined, isWebApp );
      isMounted.current = true;
    } else {
      callAnalyticsApi(defaultArgs, isWebApp);
    }
  }, [appId, isWebApp]);

  return (
    <LoaderAdvanced
      show={loader || false}
      message={insideLoader}
      backgroundStyle={{
        backgroundColor: 'rgba(255,255,255,0.6)',
      }}
    >
      <div className={classNames('session-stat-wrapper')}>
        {!isNewSession && (
          <OverviewBoxes
            statBoxesResponse={statBoxesResponse}
            uniqueUserBox={uniqueUserBox}
            aggregation_list={aggregationList}
            selectedBox={selectedBox}
            series_plot_options={seriesPlotOptions}
            selectedTab={selectedTab}
          />
        )}
        <div className='session-stat-flex'>
          <div className='session-stat-big-box'>
            <Statistics
              chartRef={chartRef}
              graphData={graphData}
              groupingOptions={groupingOptions}
              group_list={groupList}
              series_plot_options={seriesPlotOptions}
              selectedBox={selectedBox}
            />
          </div>
        </div>
      </div>
      <style>
        {`
            .margin-top-10 {
              margin-top: 10px;
            }
          `}
      </style>
    </LoaderAdvanced>
  )
}
export default SessionStatistics
